// W3 – Identify papers, clean text, split into chunks. Mode: Run Once for All Items.
// Input: one item per PDF from "Extract from File" (PDF, keep source = both), so $json.text + binary.data.fileName.
const CHUNK_SIZE = 1000;   // characters per chunk (nomic-embed-text handles ~2000 tokens, so this is safe)
const OVERLAP = 150;       // characters repeated between neighbouring chunks, so sentences aren't cut off
const BATCH_SIZE = 24;     // chunks per embedding request

// Known papers. Matched on filename (incl. arXiv number) first, then on title words or author surname on the first pages.
const PAPERS = [
  { id: 'lewis2018', match: ['alternative_influence', 'alternative influence'], title: 'Alternative Influence: Broadcasting the Reactionary Right on YouTube',
    authors: ['Rebecca Lewis'], year: 2018, venue: 'Data & Society', url: 'https://datasociety.net/library/alternative-influence/',
    position: 'Qualitative network study: maps guest appearances between political YouTubers and argues the network works as a pathway from mainstream to extreme views.' },
  { id: 'ribeiro2020', match: ['ribeiro', '1908.08313', 'auditing radicalization pathways'], title: 'Auditing Radicalization Pathways on YouTube',
    authors: ['Manoel Horta Ribeiro', 'Raphael Ottoni', 'Robert West', 'Virgílio A. F. Almeida', 'Wagner Meira Jr.'], year: 2020, venue: 'ACM FAT* 2020', url: 'https://arxiv.org/abs/1908.08313',
    position: 'Supports the pipeline thesis: commenting users migrate from milder (IDW, Alt-lite) to more extreme (Alt-right) channels; recommendations make Alt-lite reachable from IDW.' },
  { id: 'ledwich2019', match: ['ledwich', '1912.11211', 'algorithmic extremism'], title: 'Algorithmic Extremism: Examining YouTube\'s Rabbit Hole of Radicalization',
    authors: ['Mark Ledwich', 'Anna Zaitsev'], year: 2019, venue: 'arXiv / First Monday', url: 'https://arxiv.org/abs/1912.11211',
    position: 'Against the algorithmic pipeline: logged-out recommendations favoured mainstream channels over fringe ones. Source of the Recfluence channel labels.' },
  { id: 'hosseinmardi2021', match: ['hosseinmardi', '2011.12843', 'consumption of radical content', 'right-wing echo chambers'], title: 'Examining the consumption of radical content on YouTube',
    authors: ['Homa Hosseinmardi', 'Amir Ghasemian', 'Aaron Clauset', 'Markus Mobius', 'David M. Rothschild', 'Duncan J. Watts'], year: 2021, venue: 'PNAS', url: 'https://arxiv.org/abs/2011.12843',
    position: 'Demand side: real user browsing data shows radical content consumption is driven mostly by user preferences, not by recommendations.' },
  { id: 'chen2023', match: ['chen', '2204.10921', 'subscriptions and external links'], title: 'Subscriptions and external links help drive resentful users to alternative and extremist YouTube videos',
    authors: ['Annie Y. Chen', 'Brendan Nyhan', 'Jason Reifler', 'Ronald E. Robertson', 'Christo Wilson'], year: 2023, venue: 'Science Advances', url: 'https://arxiv.org/abs/2204.10921',
    position: 'Exposure to alternative/extremist videos is concentrated among a small group of already-resentful users who arrive via subscriptions and external links, rarely via recommendations.' },
];

function identify(fileName, text) {
  const f = (fileName || '').toLowerCase();
  const head = text.slice(0, 4000).toLowerCase();
  return PAPERS.find(p => p.match.some(m => f.includes(m.replace(/ /g, '_')) || f.includes(m)))
      ?? PAPERS.find(p => p.match.slice(1).some(m => head.includes(m)) || head.includes(p.title.toLowerCase().slice(0, 40)))
      ?? PAPERS.find(p => new RegExp(`\\b${p.match[0]}\\b`).test(head))   // author surname on the first page
      ?? null;
}

function clean(text) {
  let t = text
    .replace(/\r/g, '')
    .replace(/(\w)-\n(\w)/g, '$1$2')          // re-join words hyphenated across lines
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{2,}/g, '\n\n');
  // Drop the reference list / endnotes: citations add noise to semantic search
  const m = [...t.matchAll(/\n\s*(References|REFERENCES|Bibliography|ENDNOTES|Endnotes)\s*\n/g)].pop();
  if (m && m.index > t.length * 0.5) t = t.slice(0, m.index);
  return t.replace(/\s+/g, ' ').trim();
}

function chunk(text) {
  const out = [];
  let start = 0;
  while (start < text.length) {
    let end = Math.min(start + CHUNK_SIZE, text.length);
    if (end < text.length) {                       // end on a sentence boundary when one is close
      const stop = text.lastIndexOf('. ', end);
      if (stop > start + CHUNK_SIZE * 0.6) end = stop + 1;
    }
    const piece = text.slice(start, end).trim();
    if (piece.length > 80) out.push(piece);         // skip tiny fragments (page numbers etc.)
    if (end >= text.length) break;
    start = Math.max(end - OVERLAP, start + 1);
    const space = text.indexOf(' ', start);          // don't start mid-word
    if (space !== -1 && space - start < 30) start = space + 1;
  }
  return out;
}

const papers = [], chunks = [], skipped = [];
for (const item of $input.all()) {
  const fileName = item.binary?.data?.fileName ?? item.json.fileName ?? '';
  const raw = item.json.text ?? '';
  const meta = identify(fileName, raw);
  if (!meta) { skipped.push(fileName || '(unnamed pdf)'); continue; }
  const { match, ...paper } = meta;
  const pieces = chunk(clean(raw));
  papers.push({ ...paper, fileName, chunkCount: pieces.length });
  pieces.forEach((text, index) => chunks.push({
    id: `${paper.id}-${String(index).padStart(4, '0')}`, paperId: paper.id, index, text,
    // nomic-embed-text expects this prefix on documents (queries use "search_query: ")
    embedText: `search_document: ${paper.title}. ${text}`,
  }));
}

const batches = [];
for (let i = 0; i < chunks.length; i += BATCH_SIZE) batches.push(chunks.slice(i, i + BATCH_SIZE));

return [{ json: { papers, skipped, chunkCount: chunks.length, batches } }];

// W3 – Paper nodes + links into the graph. Mode: Run Once for All Items.
// Removes old chunks first, so re-running W3 after changing the chunking never leaves stale chunks behind.
const { papers, skipped } = $input.first().json;
if (!papers.length) throw new Error(`No known papers found. Skipped files: ${skipped.join(', ') || 'none'}`);

const statement = `
CALL () { MATCH (c:Chunk) DETACH DELETE c }
UNWIND $papers AS p
MERGE (paper:Paper {id: p.id})
SET paper.title = p.title, paper.authors = p.authors, paper.year = p.year, paper.venue = p.venue,
    paper.url = p.url, paper.position = p.position, paper.fileName = p.fileName, paper.chunkCount = p.chunkCount
WITH collect(paper) AS written
CALL () {
  MATCH (lewis:Paper {id: 'lewis2018'}), (person:Person)
  MERGE (lewis)-[:DESCRIBES {source: 'Lewis 2018, Fig. 1 + Appendix B'}]->(person)
}
CALL () {
  MATCH (ledwich:Paper {id: 'ledwich2019'}), (c:Channel)
  MERGE (ledwich)-[:CLASSIFIES {source: 'Recfluence dataset (Ledwich & Zaitsev)'}]->(c)
}
RETURN size(written) AS papers`;

return [{ json: { papers: papers.map(p => `${p.id} (${p.chunkCount} chunks)`), skipped, body: { statement, parameters: { papers } } } }];

// W3 – One item per batch of chunks, for the embedding loop. Mode: Run Once for All Items.
const { batches } = $('Chunk papers').first().json;
return batches.map((chunks, i) => ({ json: { batch: i + 1, of: batches.length, chunks } }));

// W3 – Join embeddings back onto their chunks and build the Neo4j write. Mode: Run Once for All Items.
const { chunks, batch, of } = $('One batch at a time').first().json;
const { embeddings } = $input.first().json;
if (!embeddings || embeddings.length !== chunks.length) {
  throw new Error(`Batch ${batch}: got ${embeddings?.length ?? 0} embeddings for ${chunks.length} chunks`);
}
if (embeddings[0].length !== 768) {
  throw new Error(`Embedding has ${embeddings[0].length} dimensions; the vector index expects 768. Check the model name.`);
}
const rows = chunks.map((c, i) => ({ id: c.id, paperId: c.paperId, index: c.index, text: c.text, embedding: embeddings[i] }));

const statement = `
UNWIND $rows AS r
MATCH (p:Paper {id: r.paperId})
MERGE (c:Chunk {id: r.id})
SET c.paperId = r.paperId, c.index = r.index, c.text = r.text, c.embedding = r.embedding
MERGE (p)-[:HAS_CHUNK]->(c)
RETURN count(c) AS written`;

return [{ json: { batch, of, count: rows.length, body: { statement, parameters: { rows } } } }];

// Fail loudly if Neo4j reports an error. Covers both cases: an HTTP error status
// (the node fails by itself) and a 2xx response with an "errors" list in the body.
for (const item of $input.all()) {
  const errors = item.json.errors ?? [];
  if (errors.length) {
    throw new Error(`Neo4j error: ${errors[0].code} – ${errors[0].message}`);
  }
}
return $input.all();

// Fail loudly if Neo4j reports an error. Covers both cases: an HTTP error status
// (the node fails by itself) and a 2xx response with an "errors" list in the body.
for (const item of $input.all()) {
  const errors = item.json.errors ?? [];
  if (errors.length) {
    throw new Error(`Neo4j error: ${errors[0].code} – ${errors[0].message}`);
  }
}
return $input.all();
